Map<String, PostalLocation>? _postalIndex;

Map<String, PostalLocation> _getPostalIndex() {
  if (_postalIndex != null) return _postalIndex!;
  final map = <String, PostalLocation>{};
  for (final loc in postalLocations) {
    if (!map.containsKey(loc.postalCode)) {
      map[loc.postalCode] = loc;
    }
  }
  _postalIndex = map;
  return map;
}

PostalLocation? lookupPostalCode(dynamic input) {
  if (input == null) return null;
  final code = input.toString().trim().padLeft(5, '0');
  final map = _getPostalIndex();
  if (map.containsKey(code)) {
    return map[code];
  }
  final numCode = int.tryParse(code);
  if (numCode != null) {
    for (final range in _districtRanges) {
      if (numCode >= range.$3 && numCode <= range.$4) {
        return PostalLocation(
          postalCode: code,
          city: "${range.$1} Area",
          district: range.$1,
          province: range.$2,
        );
      }
    }
  }
  return null;
}

List<PostalLocation> searchLocations(String query) {
  final q = query.trim().toLowerCase();
  if (q.isEmpty) return const [];
  final terms = [q];
  if (_searchAliases.containsKey(q)) {
    terms.add(_searchAliases[q]!);
  }
  final results = <PostalLocation>[];
  for (final loc in postalLocations) {
    final code = loc.postalCode.toLowerCase();
    final city = loc.city.toLowerCase();
    final dist = loc.district.toLowerCase();
    final prov = loc.province.toLowerCase();
    if (terms.any((t) => code.contains(t) || city.contains(t) || dist.contains(t) || prov.contains(t))) {
      results.add(loc);
    }
  }
  return results;
}
